query (
  $whereI: InventoryWhereInput,
  $whereM: MasterInventoryWhereInput,
  $whereShipmentLine: ShipmentLineWhereInput!,
  $whereLoad: LoadWhereInput!
) {
  inventory(where: $whereI) {
  total
  edges {
      node {
        id
				active
        barcode
        number
        trackingNumber
        locationId
        location{
          facilityId
        }
        productId
        productStrategyProcessId
        lotId
        locationId
        workOrderProcessId
        masterInventoryId
        shipmentLineId
        inventoryStatus {
          id
          name
          active
          suspect
          containment
          productionLoaded
          shippable
      staged
      loaded
      shipped
        }
        quantity {
          value
          unitId
        }
        weightUnit {
          id
          code
        }
        grossWeight
        netWeight
        tareWeight


      }
    }
  }
  master: masterInventory(where: $whereM) {
  total
    edges {
      node {
        id
        number
        active
        masterInventoryStatus {
          id
          name
          active
          containment
          empty
          loaded
          mergePrevent
          movePrevent
          picked
          productionLoaded
          productionPrevent
          received
          shipPrevent
          shipped
          splitPrevent
          staged
          system
          usable
          color
          externalId
          message
          customData
          integrationData
        }
        locationId
        inventory{
          edges{
            node{
              id
              productId
              quantity{value}
              shipmentLineId
              shipmentLine{
                id
                loadedQuantity{value}
                quantity{ value }
              }
            }
          }
        }
      }
    }
  }
  shipmentLine(where: $whereShipmentLine){
    edges{
      node{
        id
        shipmentId
        shipment{ number }
        productId
        stagedQuantity{ value }
        quantity{ value }
        loadedQuantity{ value }
        shippedQuantity{ value }
        product{
          code
          name
        }
      }
    }
  }
  load(where: $whereLoad){
    edges{
      node{
        facilityId
        locationId
      }
    }
  }

}

